  7→<style>
  8→  :root {
  9→    --bg: #faf8f5; --card: #fffefb; --text: #1c1917; --muted: #78716c;
 10→    --border: #e7e5e4; --accent: #1c1917; --red: #b91c1c; --green: #166534;
 11→    --tag-bg: #f5f5f4; --tag-text: #44403c;
 12→    --header-from: #292524; --header-to: #57534e;
 13→  }
 14→  * { box-sizing: border-box; margin: 0; padding: 0; }
 15→  body {
 16→    font-family: -apple-system, "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
 17→    background: var(--bg); color: var(--text); line-height: 1.65; padding: 24px 16px;
 18→  }
 19→  .container { max-width: 880px; margin: 0 auto; }
 20→  /* 编辑部资讯风：纸感头 + 时间线，非通用渐变卡壳 */
 21→  .header {
 22→    background: linear-gradient(180deg, #f5f0e8 0%, var(--card) 100%);
 23→    color: var(--text); border-radius: 0; padding: 28px 8px 20px; margin-bottom: 8px;
 24→    border-bottom: 3px double var(--accent);
 25→  }
 26→  .header h1 {
 27→    font-family: "Songti SC", "Noto Serif SC", "Source Han Serif SC", Georgia, serif;
 28→    font-size: 1.75rem; font-weight: 700; letter-spacing: 0.04em;
 29→  }
 30→  .header .meta { color: var(--muted); font-size: 0.85rem; margin-top: 8px; }
 31→  .tldr {
 32→    background: var(--card); border: none; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
 33→    border-radius: 0; padding: 16px 4px; margin-bottom: 20px;
 34→  }
 35→  .tldr h2 { font-size: 0.8rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
 36→  .tldr ul { padding-left: 1.1em; font-size: 0.95rem; }
 37→  .tldr li { margin: 6px 0; }
 38→  .stats {
 39→    display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 20px;
 40→  }
 41→  .stat {
 42→    background: transparent; border: none; border-right: 1px solid var(--border);
 43→    border-radius: 0; padding: 8px 16px 8px 0; min-width: 100px; flex: 1;
 44→  }
 45→  .stat:last-child { border-right: none; }
 46→  .stat .label { font-size: 0.72rem; color: var(--muted); letter-spacing: 0.06em; }
 47→  .stat .value { font-size: 1.35rem; font-weight: 700; color: var(--accent); margin-top: 2px; font-variant-numeric: tabular-nums; }
 48→  h2.section {
 49→    font-family: "Songti SC", "Noto Serif SC", Georgia, serif;
 50→    font-size: 1.15rem; font-weight: 600; margin: 32px 0 14px;
 51→    padding-bottom: 8px; border-bottom: 1px solid var(--accent); color: var(--accent);
 52→  }
 53→  .article {
 54→    background: transparent; border: none; border-left: 2px solid #d6d3d1;
 55→    border-radius: 0; padding: 4px 0 18px 18px; margin-bottom: 8px; position: relative;
 56→  }
 57→  .article::before {
 58→    content: ""; position: absolute; left: -5px; top: 10px; width: 8px; height: 8px;
 59→    border-radius: 50%; background: var(--accent);
 60→  }
 61→  .article .title { font-size: 1.05rem; font-weight: 650; margin-bottom: 6px; line-height: 1.4; }
 62→  .article .meta-row {
 63→    font-size: 0.8rem; color: var(--muted); margin-bottom: 10px;
 64→    display: flex; flex-wrap: wrap; gap: 10px; align-items: center;
 65→  }
 66→  .tag {
 67→    display: inline-block; background: var(--tag-bg); color: var(--tag-text);
 68→    font-size: 0.72rem; padding: 2px 8px; border-radius: 2px; font-weight: 500;
 69→  }
 70→  .article .body { font-size: 0.92rem; color: #333; }
 71→  .article .body p { margin-bottom: 0.7em; }
 72→  .article .body p:last-child { margin-bottom: 0; }
 73→  .article a { color: #9a3412; text-decoration: none; border-bottom: 1px dotted #c2410c; }
 74→  .article a:hover { text-decoration: none; border-bottom-style: solid; }
 75→  .impact { margin-top: 10px; padding: 10px 12px; background: #f5f5f4; border-left: 3px solid var(--accent);
 76→    font-size: 0.88rem; color: #374151; }
 77→  .impact strong { color: var(--accent); }
 78→  .telegraph-list { list-style: none; border-left: 2px solid #d6d3d1; padding-left: 16px; }
 79→  .telegraph-list li {
 80→    background: transparent; border: none; border-bottom: 1px dashed var(--border); border-radius: 0;
 81→    padding: 10px 0; margin-bottom: 0; font-size: 0.88rem; position: relative;
 82→  }
 83→  .telegraph-list li::before {
 84→    content: ""; position: absolute; left: -21px; top: 16px; width: 8px; height: 8px;
 85→    border-radius: 50%; background: #a8a29e;
 86→  }
 87→  .telegraph-list .time { color: var(--muted); font-size: 0.78rem; margin-right: 8px; font-variant-numeric: tabular-nums; font-weight: 600; }
 88→  .footer {
 89→    margin-top: 28px; padding-top: 12px; border-top: 1px solid var(--border);
 90→    color: var(--muted); font-size: 0.75rem; text-align: center;
 91→  }
 92→</style>
 93→</head>
 94→<body>
 95→<div class="container">
 96→
 97→  <div class="header">
 98→    <h1>财经新闻汇总</h1>
 99→    <div class="meta">日期：YYYY-MM-DD · 时段：HH:MM–HH:MM HKT · 去重后 N 条</div>
100→  </div>
101→
102→  <!-- 首屏结论先行（编辑部资讯风） -->
103→  <div class="tldr">
104→    <h2>今日要点</h2>
105→    <ul>
106→      <li>[3–6 条一句话要点：事件 + 市场含义]</li>
107→    </ul>
108→  </div>
109→
110→  <div class="stats">
111→    <div class="stat"><div class="label">抓取条数</div><div class="value">X</div></div>
112→    <div class="stat"><div class="label">去重后</div><div class="value">Y</div></div>
113→    <div class="stat"><div class="label">主题数</div><div class="value">Z</div></div>
114→  </div>
115→
116→  <!-- 按主题重复以下区块 -->
117→  <h2 class="section">一、[主题名，如：国际宏观 / 货币政策]</h2>
118→
119→  <div class="article">
120→    <div class="title">[新闻标题]</div>
121→    <div class="meta-row">
122→      <span>HH:MM</span>
123→      <span class="tag">[来源]</span>
124→      <a href="URL" target="_blank" rel="noopener">原文链接</a>
125→    </div>
126→    <div class="body">
127→      <p>[深度概括第 1 段：核心事件]</p>
128→      <p>[第 2 段：关键数据 / 人物表态 / 背景]</p>
129→      <p>[第 3 段：市场影响]</p>
130→    </div>
131→    <div class="impact"><strong>所以呢：</strong>[一句话操作/观察含义，非买卖建议]</div>
132→  </div>
133→
134→  <!-- 能力二：快讯/电报模式可用下方列表结构 -->
135→  <!--
136→  <h2 class="section">市场快讯</h2>
137→  <ul class="telegraph-list">
138→    <li><span class="time">14:32</span>[title｜content 归一化文本]</li>
139→  </ul>
140→  -->
141→
142→  <div class="footer">
143→    以上内容基于公开资讯整理，仅供市场热度追踪与投顾沟通参考，不构成投资建议。
144→  </div>
145→</div>
146→</body>
147→</html>
